    let Dialog::FaceModel { info, accepted, .. } = &dlg else { panic!("{dlg:?}") };
    assert!(!accepted);
    assert_eq!((info["download"].as_str(), info["host"].as_str()), (Some("yunet-2023mar"), Some("github.com")));
