    h.request("ui.clickWidget", json!({"id": "button:settingsGridBadges-1"}), t);
    assert_eq!(h.app.ui.settings.grid_badges, crate::state::GridBadges::Always);
    h.request("ui.scroll", json!({"dy": 700.0}), t);
